using System;using System.Net;using System.IO;using System.Threading.Tasks;
public class ProxyProbe {public string Kind,Channel;public DateTime CheckedUtc;}
public class ProxyHealthNotice {public string Key,Text;}
public sealed class ProxyHealthMonitor {
 Task<ProxyProbe> work;DateTime next,lastProbe,lastNotice;int failures;string channel="";public string Status="等待代理检测";
 static string Channel(MonitorConfig c){return c.ExitProxyMode+"|"+c.ExitProxyAddress;}
 internal static bool IsTimeout(Exception error){for(var e=error;e!=null;e=e.InnerException){var web=e as WebException;var socket=e as System.Net.Sockets.SocketException;if(e is TimeoutException||web!=null&&web.Status==WebExceptionStatus.Timeout||socket!=null&&socket.SocketErrorCode==System.Net.Sockets.SocketError.TimedOut)return true;}return false;}
 public static ProxyProbe Probe(string mode,string address){string kind="unavailable";try{var proxy=NetworkExit.Proxy(mode,address);var target=new Uri("https://ipwho.is/");if(proxy==null||proxy.IsBypassed(target)||proxy.GetProxy(target)==target)kind="bypassed";else{NetworkExit.Fetch(mode,address);kind="ok";}}catch(WebException e){kind=e.Status==WebExceptionStatus.Timeout?"timeout":e.Status==WebExceptionStatus.ConnectFailure||e.Status==WebExceptionStatus.ProxyNameResolutionFailure?"unreachable":"service-error";}catch(IOException e){kind=IsTimeout(e)?"timeout":"service-error";}catch(ArgumentException){kind="configuration-error";}catch(InvalidOperationException){kind="service-error";}return new ProxyProbe{Kind=kind,Channel=mode+"|"+address,CheckedUtc=DateTime.UtcNow};}
 public ProxyHealthNotice Observe(ProxyProbe result,MonitorConfig cfg,DateTime now){if(!cfg.ExitLookupEnabled||!cfg.ProxyTimeoutAlerts){failures=0;Status="后台代理提醒已暂停";return null;}if(result==null||result.Channel!=Channel(cfg)||result.CheckedUtc<=lastProbe||result.CheckedUtc>now||now-result.CheckedUtc>TimeSpan.FromMinutes(5))return null;lastProbe=result.CheckedUtc;
  bool failed=result.Kind=="timeout"||result.Kind=="unreachable";if(!failed){failures=0;Status=result.Kind=="ok"?"代理通道检测通过 · "+result.CheckedUtc.ToLocalTime().ToString("HH:mm:ss"):result.Kind=="bypassed"?"当前通道未使用HTTP代理，未判断代理超时":result.Kind=="configuration-error"?"代理设置无效，请检查检测通道":"检测服务暂不可用，不能据此认定代理超时";return null;}
  failures++;int threshold=Math.Max(1,Math.Min(5,cfg.ProxyFailureCount));Status="代理通道"+(result.Kind=="timeout"?"超时":"无法连接")+" · 连续 "+failures+" 次";if(failures<threshold||lastNotice!=default(DateTime)&&now-lastNotice<TimeSpan.FromSeconds(Math.Max(30,Math.Min(3600,cfg.ProxyCooldownSeconds))))return null;lastNotice=now;return new ProxyHealthNotice{Key="monitor:proxy:"+now.Ticks,Text="网络侦察提醒：代理通道连续 "+failures+" 次"+(result.Kind=="timeout"?"检测超时（每次8秒）":"无法连接")+"，请检查代理软件或节点。检测服务或网络故障也可能导致此结果，尚不能确定VPN已经掉线。"};
 }
 public ProxyHealthNotice Poll(MonitorConfig cfg,DateTime now){string selected=Channel(cfg);if(selected!=channel){channel=selected;failures=0;lastProbe=default(DateTime);next=DateTime.MinValue;}ProxyHealthNotice notice=null;if(work!=null&&work.IsCompleted){if(work.Status==TaskStatus.RanToCompletion)notice=Observe(work.Result,cfg,now);else{var error=work.Exception;Status="后台代理检测未完成，等待下次检查";}work=null;}
  if(!cfg.ExitLookupEnabled||!cfg.ProxyTimeoutAlerts){failures=0;next=DateTime.MinValue;Status="后台代理提醒已暂停";return null;}if(work==null&&now>=next&&Environment.GetEnvironmentVariable("CONAN_PET_TEST_MODE")!="1"){next=now.AddSeconds(Math.Max(15,Math.Min(300,cfg.ProxyCheckSeconds)));string mode=cfg.ExitProxyMode,address=cfg.ExitProxyAddress;work=Task.Run(()=>Probe(mode,address));}return notice;
 }
}
